import{j as e,B as y,T as n,Z as f,bd as g,as as w,at as b}from"./mui.D2HgYcpb.js";import{H as v}from"./HeroSection.DVLbC8ok.js";import{X as k,P as x,A as l,h as c,R as h,T as u,E as o}from"./index.CHO4vGx3.js";import"./vendor.Cgg2GOmP.js";function G(){const d=[{type:"h2",text:"What is this Privacy Policy for?"},{type:"p",text:"This privacy policy is for this website and governs the privacy of its users who choose to use it. The policy sets out the different areas where user privacy is concerned and outlines the obligations & requirements of the users, the website and website owners. Furthermore the way this website processes, stores and protects user data and information will also be detailed within this policy."},{type:"h2",text:"GDPR Statement"},{type:"p",text:"Go Airport Parking LTD has built its business on customer trust and places a high importance on information security within our company."},{type:"p",text:"The General Data Protection Regulation (GDPR) (Regulation (EU) 2016/679) is a privacy and data protection regulation in the European Union (EU) became enforceable from May 25th 2018 and requires no enabling legislation so automatically becomes binding and applicable on that date. The GDPR imposes new obligations on organisations that control or process relevant personal data and introduces new rights and protections for EU data subjects. The GDPR applies to data processing carried out by organisations operating within the EU. It also applies to organisations outside the EU that offer goods or services to individuals in the EU."},{type:"p",text:"Go Airport Parking LTD will comply with the GDPR as a processor and controller of data. We are working with our suppliers and partner organisations to ensure they can also meet these obligations. As we work towards best practice and compliance, and our efforts are concentrated in these key areas:"},{type:"ul",items:["Website Data Collection & Consent, Privacy Policy: we will only collect and use customer data in accordance with our GDPR obligations.","Training & Awareness: we will undertake training across the company on the GDPR and its impact on the new policies, procedures, and responsibilities of staff & stakeholders.","Supplier & Partner relationships: where relevant and related, we will be using all reasonable endeavours to ensure that our third party and suppliers are complying with the GDPR.","Technology: we will be reviewing our technology platforms to analyse their operation, security, compliance in order to ensure that they meet the standards we have laid down and identify any gaps and risks."]},{type:"p",text:"Go Airport Parking LTD is totally committed to GDPR compliance."},{type:"h2",text:"What personal information does Go Airport Parking LTD ask for?"},{type:"p",text:"During the booking or travel card application process we may ask for your name, postal address, e-mail address, car registration number and a contact telephone number. We will also ask for your credit/debit card details (including card number, cardholder name and expiry date) in order to take payment and confirm your booking."},{type:"h2",text:"How does Go Airport Parking LTD use your information?"},{type:"ul",items:["We need your 'name' so we can confirm to the lounge, car park operator, or travel card provider who the booking/application is for","For parking and lounge bookings we need your 'credit card' details so that we can collect payment for your booking","We need your 'name' and 'address' to confirm that the credit card belongs to you","We might use your 'telephone number' or 'e-mail address' in the unlikely event that we need to contact you urgently about your booking","For travel card applications we will send your Name, Email Address, Address, Contact Number and Date of Birth to our selected travel card provider. We also receive your Email Address back from the provider when you complete your application, this allows us to manage the process","If you have subscribed to receive direct marketing from us, we may also use this information to let you know about any special offers/promotions we think would be of interest to you","We may also use your IP (Internet Protocol) address to diagnose problems with our server and administer the site - monitoring visitor traffic patterns and site usage to help us develop and improve the Go Airport Parking LTD website further"]},{type:"h2",text:"How does Go Airport Parking LTD protect customer information?"},{type:"p",text:"All the information you give us is protected by a secure server. The secure server software SSL (Secure Socket Layers) encrypts all information you enter before it is sent to us. We also have a Firewall (security software) in place to protect our internal information from the Internet."},{type:"h2",text:"Will Go Airport Parking LTD disclose any of this personal information to third parties?"},{type:"p",text:"Go Airport Parking LTD will only disclose your details to our suppliers for the fulfilment of your booked services or travel card application. We will only pass the information required to fulfil that service by the supplier. We will never pass on your details to other companies for marketing purposes. We will never disclose credit/debit card information unless the law requires us to do so. If we are required to disclose any personal information by any applicable law, regulation or legal process we will only disclose the minimum information required to perform the booking function or manage our legal obligations."},{type:"h2",text:"Will Go Airport Parking LTD use the information I give for direct marketing?"},{type:"p",text:"Go Airport Parking LTD will only use your information for direct marketing activities, such as offers and product updates if you have given us your permission for us to do so. If you do not want any contact with us, apart from that which is necessary for us to give you our normal level of service, then you can unsubscribe at any time."},{type:"h2",text:"The Website"},{type:"p",text:"This website and its owners take a proactive approach to user privacy and ensure the necessary steps are taken to protect the privacy of its users throughout their visiting experience. This website complies to all UK national laws and requirements for user privacy."},{type:"h2",text:"Use of Cookies"},{type:"p",text:"This website uses cookies to better the users experience while visiting the website. Where applicable this website uses a cookie control system allowing the user on their first visit to the website to allow or disallow the use of cookies on their computer / device. This complies with recent legislation requirements for websites to obtain explicit consent from users before leaving behind or reading files such as cookies on a user's computer / device."},{type:"p",text:"Cookies are small files saved to the user's computers hard drive that track, save and store information about the user's interactions and usage of the website. This allows the website, through its server to provide the users with a tailored experience within this website."},{type:"p",text:"Users are advised that if they wish to deny the use and saving of cookies from this website on to their computers hard drive they should take necessary steps within their web browsers security settings to block all cookies from this website and its external serving vendors."},{type:"p_linked",parts:["This website uses tracking software to monitor its visitors to better understand how they use it. This software is provided by Google Analytics which uses cookies to track visitor usage. The software will save a cookie to your computers hard drive in order to track and monitor your engagement and usage of the website, but will not store, save or collect personal information. You can read Google's privacy policy here for further information ",{href:"https://www.google.com/privacy.html",label:"https://www.google.com/privacy.html"},"."]},{type:"p",text:"Other cookies may be stored to your computers hard drive by external vendors when this website uses referral programs, sponsored links or adverts. Such cookies are used for conversion and referral tracking and typically expire after 30 days, though some may take longer. No personal information is stored, saved or collected."},{type:"h2",text:"Contact & Communication"},{type:"p",text:"This website and its owners use any information submitted to provide you with further information about the products / services they offer or to assist you in answering any questions or queries you may have submitted. This includes using your details to subscribe you to any email newsletter program the website operates but only if this was made clear to you and your express permission was granted when submitting any form to email process. Or whereby you the consumer have previously purchased from or enquired about purchasing from the company a product or service that the email newsletter relates to. This is by no means an entire list of your user rights in regard to receiving email marketing material. S2A LIMITED's Data Protection Registration Number is: ZA157121."},{type:"h2",text:"Email Newsletter"},{type:"p",text:"This website operates an email newsletter program, used to inform subscribers about products and services supplied by this website. Users can subscribe through an online automated process should they wish to do so but do so at their own discretion. Some subscriptions may be manually processed through prior written agreement with the user."},{type:"p",text:"Email marketing campaigns published by this website or its owners may contain tracking facilities within the actual email. Subscriber activity is tracked and stored in a database for future analysis and evaluation. Such tracked activity may include; the opening of emails, forwarding of emails, the clicking of links within the email content, times, dates and frequency of activity [this is by no far a comprehensive list]. This information is used to refine future email campaigns and supply the user with more relevant content based around their activity."},{type:"p",text:"In compliance with UK Spam Laws and the Privacy and Electronic Communications Regulations 2003 subscribers are given the opportunity to un-subscribe at any time through an automated system. This process is detailed at the footer of each email campaign. If an automated un-subscription system is unavailable clear instructions on how to un-subscribe will by detailed instead."},{type:"h2",text:"Social Media Platforms"},{type:"p",text:"Communication, engagement and actions taken through external social media platforms that this website and its owners participate on are custom to the terms and conditions as well as the privacy policies held with each social media platform respectively."},{type:"p",text:"Users are advised to use social media platforms wisely and communicate / engage upon them with due care and caution in regard to their own privacy and personal details. This website nor its owners will ever ask for personal or sensitive information through social media platforms and encourage users wishing to discuss sensitive details to contact them through primary communication channels such as by telephone or email."},{type:"p",text:"This website may use social sharing buttons which help share web content directly from web pages to the social media platform in question. Users are advised before using such social sharing buttons that they do so at their own discretion and note that the social media platform may track and save your request to share a web page respectively through your social media platform account."}],p=120,m=70;return e.jsxs(e.Fragment,{children:[e.jsx(v,{title:"Privacy Policy",subtitle:"How Go Airport Parking LTD collects, uses, and protects your data.",image:k}),e.jsx(x,{children:e.jsx(y,{sx:{my:{xs:3,md:5}},children:d.map((t,i)=>{const s=p+i*m;return t.type==="h2"?e.jsxs(l,{type:"slide-up",distance:16,duration:680,delay:s,easingTransform:o,easingOpacity:o,threshold:u,rootMargin:h,once:!0,style:c,children:[e.jsx(n,{variant:"h5",sx:{fontWeight:800,mt:i===0?0:4,mb:1},children:t.text}),e.jsx(f,{sx:{mb:2}})]},i):t.type==="p"?e.jsx(l,{type:"fade",duration:560,delay:s,easingTransform:o,easingOpacity:o,threshold:u,rootMargin:h,once:!0,style:c,children:e.jsx(n,{variant:"body2",color:"text.secondary",sx:{mb:1.5},children:t.text})},i):t.type==="p_linked"?e.jsx(l,{type:"fade",duration:560,delay:s,easingTransform:o,easingOpacity:o,threshold:u,rootMargin:h,once:!0,style:c,children:e.jsx(n,{variant:"body2",color:"text.secondary",sx:{mb:1.5},children:t.parts.map((r,a)=>typeof r=="string"?e.jsx("span",{children:r},a):e.jsx(g,{href:r.href,underline:"hover",target:"_blank",rel:"noopener",children:r.label},a))})},i):t.type==="ul"?e.jsx(l,{type:"fade",duration:560,delay:s,easingTransform:o,easingOpacity:o,threshold:u,rootMargin:h,once:!0,style:c,children:e.jsx(w,{dense:!0,sx:{pl:5,mb:1.5,listStyleType:"disc","& .MuiListItem-root":{display:"list-item",pl:.5,mb:.5}},children:t.items.map((r,a)=>e.jsx(b,{disableGutters:!0,children:e.jsx(n,{variant:"body2",color:"text.secondary",children:r})},a))})},i):null})})})]})}export{G as default};
